/**
 * Firestore implementation of `JobsRepository`.
 *
 * Document layout:
 *   users/{uid}/jobs/{jobId}
 *
 * `{jobId}` is a stable Firestore document ID, generated by Firestore on create and
 * never changed. It is NOT the Google Sheet row number -- see `ExternalSheetMirror`
 * in the domain model for why those two must not be conflated.
 *
 * All Firestore-specific concerns stop here: timestamps arrive as `Timestamp` and leave
 * as ISO-8601 strings, enum values are validated against the domain, and nested
 * structures are shape-checked. Nothing Firestore-shaped reaches `src/domain/job.ts`.
 */

import { firestore } from '../../services/firebase';
import {
  JOB_APPLICATION_STATUSES,
  JOB_APPROVAL_STATUSES,
  JOB_CONTACT_EMAIL_SOURCES,
  JOB_DEADLINE_SOURCES,
  JOB_FOLLOW_UP_STATUSES,
  JOB_INTAKE_STATUSES,
  JOB_RAW_SOURCES,
  JOB_SHEET_SYNC_STATUSES,
  RESUME_SUGGESTION_SCHEMA_VERSION,
  computeDedupeKey,
  createJob,
  isSuggestionActionType,
  isSuggestionCategory,
  isSuggestionPriority,
} from '../../domain/job';
import type {
  CreateJobInput,
  IsoDateTime,
  Job,
  JobApplicationStatus,
  JobApprovalStatus,
  JobContactEmailSource,
  JobDeadlineSource,
  JobFieldConfidence,
  JobFollowUpStatus,
  JobIntakeStatus,
  JobRawSource,
  JobSheetSyncStatus,
  MatchBreakdown,
  ResumeSuggestions,
  SuggestionActionType,
  SuggestionCategory,
  SuggestionPriority,
} from '../../domain/job';
import type { JobPatch, JobsRepository, ListJobsOptions } from './types';

const USERS_COLLECTION = 'users';
const JOBS_SUBCOLLECTION = 'jobs';

const APPROVAL_FIELDS = ['approvalStatus', 'approvedAt', 'approvedBy'] as const;

/** Thrown when an operation targets a job ID that does not exist. */
export class JobNotFoundError extends Error {
  constructor(jobId: string) {
    super(`No job found with id "${jobId}"`);
    this.name = 'JobNotFoundError';
  }
}

/** Thrown when an approval transition is not allowed from the current state. */
export class ApprovalTransitionError extends Error {
  constructor(reason: string) {
    super(reason);
    this.name = 'ApprovalTransitionError';
  }
}

/** Thrown when a review precondition is not met. */
export class ReviewPreconditionError extends Error {
  constructor(reason: string) {
    super(reason);
    this.name = 'ReviewPreconditionError';
  }
}

// -- Boundary coercion ---------------------------------------------------------
//
// Documents in this collection are not guaranteed to be canonical: legacy Job Tracker
// records share the path and use different field names and value shapes. These helpers
// read defensively and fall back to documented domain defaults. They never write back,
// so reading is non-destructive and no migration is implied.

type PlainObject = Record<string, unknown>;

function isPlainObject(value: unknown): value is PlainObject {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function coerceString(value: unknown): string | null {
  return typeof value === 'string' ? value : null;
}

function coerceNumber(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

function coerceCount(value: unknown): number {
  const parsed = coerceNumber(value);
  return parsed === null || parsed < 0 ? 0 : parsed;
}

/** Match score is only meaningful in 0..100. Anything else means "not scored". */
function coerceMatchScore(value: unknown): number | null {
  const parsed = coerceNumber(value);
  return parsed !== null && parsed >= 0 && parsed <= 100 ? parsed : null;
}

function coerceBoolean(value: unknown, fallback: boolean): boolean {
  return typeof value === 'boolean' ? value : fallback;
}

function coerceEnum<T extends string>(value: unknown, allowed: readonly T[], fallback: T): T {
  return typeof value === 'string' && (allowed as readonly string[]).includes(value)
    ? (value as T)
    : fallback;
}

/**
 * Normalizes any timestamp representation to an ISO-8601 string: a Firestore
 * `Timestamp` (duck-typed via `toDate()`), an existing ISO string, epoch
 * milliseconds, or a `Date`. Returns null for anything unrecognized.
 */
function coerceIso(value: unknown): IsoDateTime | null {
  if (value === null || value === undefined) return null;

  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return null;
    // Legacy Job Tracker records store sentinels such as "No Deadline" and "TBD" in
    // `deadline`. Those are not timestamps, so they read as "no deadline" instead of
    // leaking into a field typed as ISO-8601 and producing silent Invalid Date bugs
    // downstream. Nothing is written back, so this is boundary normalization, not a
    // migration of the stored record.
    const parsed = new Date(trimmed);
    return Number.isNaN(parsed.getTime()) ? null : trimmed;
  }

  if (typeof value === 'number' && Number.isFinite(value)) {
    const fromEpoch = new Date(value);
    return Number.isNaN(fromEpoch.getTime()) ? null : fromEpoch.toISOString();
  }

  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : value.toISOString();
  }

  if (typeof value === 'object') {
    const candidate = value as { toDate?: unknown };
    if (typeof candidate.toDate === 'function') {
      const date = (candidate.toDate as () => unknown)();
      if (date instanceof Date && !Number.isNaN(date.getTime())) return date.toISOString();
    }
  }

  return null;
}

function coerceFieldConfidence(value: unknown): JobFieldConfidence | null {
  if (!isPlainObject(value)) return null;
  const result: PlainObject = {};
  for (const [key, entry] of Object.entries(value)) {
    const score = coerceNumber(entry);
    if (score !== null) result[key] = score;
  }
  return Object.keys(result).length > 0 ? (result as JobFieldConfidence) : null;
}

function coerceMatchBreakdown(value: unknown): MatchBreakdown | null {
  if (!Array.isArray(value)) return null;
  const entries = value.filter(isPlainObject).map((entry) => ({
    criterion: coerceString(entry.criterion) ?? '',
    score: coerceNumber(entry.score) ?? 0,
    weight: coerceNumber(entry.weight) ?? 0,
    rationale: coerceString(entry.rationale),
  }));
  return entries.length > 0 ? entries : null;
}

/**
 * Reads `Job.resumeSuggestions`, which is a versioned envelope rather than a bare list.
 *
 * Three states are kept distinct on purpose:
 *
 * - not an object, or a schema this build does not understand → `null` ("never generated");
 * - a valid envelope whose `suggestions` array is empty → `{ schemaVersion, suggestions: [] }`
 *   ("generated, nothing worth recommending");
 * - a valid envelope with entries → the entries that survive validation.
 *
 * An entry missing any of its eight fields is dropped rather than given a default: a
 * suggestion without its evidence is worse than no suggestion, because it asks to be
 * trusted. This never writes back, so dropping is non-destructive.
 */
function coerceResumeSuggestions(value: unknown): ResumeSuggestions | null {
  if (!isPlainObject(value)) return null;
  const schemaVersion = coerceNumber(value.schemaVersion);
  if (
    schemaVersion === null ||
    !Number.isInteger(schemaVersion) ||
    schemaVersion < RESUME_SUGGESTION_SCHEMA_VERSION
  ) {
    return null;
  }
  if (!Array.isArray(value.suggestions)) return null;

  const suggestions = value.suggestions.filter(
    (entry): entry is PlainObject =>
      isPlainObject(entry) &&
      typeof entry.id === 'string' &&
      entry.id.length > 0 &&
      isSuggestionPriority(entry.priority) &&
      isSuggestionCategory(entry.category) &&
      isSuggestionActionType(entry.actionType) &&
      typeof entry.title === 'string' &&
      entry.title.trim().length > 0 &&
      typeof entry.suggestion === 'string' &&
      entry.suggestion.trim().length > 0 &&
      typeof entry.jobEvidence === 'string' &&
      entry.jobEvidence.trim().length > 0 &&
      typeof entry.resumeEvidence === 'string' &&
      entry.resumeEvidence.trim().length > 0,
  );

  return {
    schemaVersion,
    suggestions: suggestions.map((entry) => ({
      id: entry.id as string,
      priority: entry.priority as SuggestionPriority,
      category: entry.category as SuggestionCategory,
      actionType: entry.actionType as SuggestionActionType,
      title: (entry.title as string).trim(),
      suggestion: (entry.suggestion as string).trim(),
      jobEvidence: (entry.jobEvidence as string).trim(),
      resumeEvidence: (entry.resumeEvidence as string).trim(),
    })),
  };
}

const INVALIDATING_FIELDS = [
  'draftSubject',
  'draftMessage',
  'selectedResumeId',
  'matchScore',
  'matchBreakdown',
  'resumeSuggestions',
] as const;

function stripsApprovalFields(patch: PlainObject): PlainObject {
  const result: PlainObject = {};
  for (const [key, value] of Object.entries(patch)) {
    if (!APPROVAL_FIELDS.includes(key as (typeof APPROVAL_FIELDS)[number])) {
      result[key] = value;
    }
  }
  return result;
}

function needsRevocation(current: Job, changes: PlainObject): boolean {
  if (current.approvalStatus !== 'approved') return false;
  for (const field of INVALIDATING_FIELDS) {
    if (field in changes) return true;
  }
  return false;
}

/** Builds a domain Job from a raw document body. */
function toJob(id: string, data: PlainObject): Job {
  const createdAt = coerceIso(data.createdAt) ?? new Date().toISOString();
  const updatedAt = coerceIso(data.updatedAt) ?? createdAt;

  return {
    id,
    schemaVersion: coerceNumber(data.schemaVersion) ?? 0,
    dedupeKey: coerceString(data.dedupeKey),
    createdAt,
    updatedAt,
    archivedAt: coerceIso(data.archivedAt),

    rawText: coerceString(data.rawText),
    rawSource: coerceEnum<JobRawSource>(data.rawSource, JOB_RAW_SOURCES, 'manual'),
    capturedAt: coerceIso(data.capturedAt),
    intakeStatus: coerceEnum<JobIntakeStatus>(data.intakeStatus, JOB_INTAKE_STATUSES, 'unparsed'),
    fieldConfidence: coerceFieldConfidence(data.fieldConfidence),

    company: coerceString(data.company),
    contactName: coerceString(data.contactName),
    contactEmail: coerceString(data.contactEmail),
    role: coerceString(data.role),
    jobUrl: coerceString(data.jobUrl),
    source: coerceString(data.source),
    location: coerceString(data.location),
    notes: coerceString(data.notes),
    deadline: coerceIso(data.deadline),
    deadlineSource: coerceEnum<JobDeadlineSource>(data.deadlineSource, JOB_DEADLINE_SOURCES, 'unknown'),
    contactEmailSource: coerceEnum<JobContactEmailSource>(
      data.contactEmailSource,
      JOB_CONTACT_EMAIL_SOURCES,
      'unknown',
    ),

    selectedResumeId: coerceString(data.selectedResumeId),
    matchScore: coerceMatchScore(data.matchScore),
    matchBreakdown: coerceMatchBreakdown(data.matchBreakdown),
    resumeSuggestions: coerceResumeSuggestions(data.resumeSuggestions),

    draftMessage: coerceString(data.draftMessage),
    draftSubject: coerceString(data.draftSubject),
    draftGeneratedAt: coerceIso(data.draftGeneratedAt),
    draftEditedByHuman: coerceBoolean(data.draftEditedByHuman, false),

    approvalStatus: coerceEnum<JobApprovalStatus>(data.approvalStatus, JOB_APPROVAL_STATUSES, 'draft'),
    approvedAt: coerceIso(data.approvedAt),
    approvedBy: coerceString(data.approvedBy),

    applicationStatus: coerceEnum<JobApplicationStatus>(
      data.applicationStatus,
      JOB_APPLICATION_STATUSES,
      'draft',
    ),

    sheetRowId: coerceNumber(data.sheetRowId),
    sheetSyncStatus: coerceEnum<JobSheetSyncStatus>(
      data.sheetSyncStatus,
      JOB_SHEET_SYNC_STATUSES,
      'never',
    ),
    sheetSyncedAt: coerceIso(data.sheetSyncedAt),

    gmailThreadId: coerceString(data.gmailThreadId),
    emailSentOn: coerceIso(data.emailSentOn),
    followUpStatus: coerceEnum<JobFollowUpStatus>(
      data.followUpStatus,
      JOB_FOLLOW_UP_STATUSES,
      'not_started',
    ),
    followUpCount: coerceCount(data.followUpCount),
    followUpLastSentAt: coerceIso(data.followUpLastSentAt),

    reminderDeadlineNotifId: coerceString(data.reminderDeadlineNotifId),
    nextReminderAt: coerceIso(data.nextReminderAt),
  };
}

/**
 * Serializes a Job for storage. `id` is omitted because it is the document ID rather
 * than a field. `undefined` values are dropped so Firestore never sees them.
 */
function toFirestoreData(job: Job): PlainObject {
  const result: PlainObject = {};
  for (const [key, value] of Object.entries(job)) {
    if (key === 'id' || value === undefined) continue;
    result[key] = value;
  }
  return result;
}

/** Drops `undefined` entries, which Firestore would otherwise reject. */
function withoutUndefined(source: PlainObject): PlainObject {
  const result: PlainObject = {};
  for (const [key, value] of Object.entries(source)) {
    if (value !== undefined) result[key] = value;
  }
  return result;
}

// -- Repository ----------------------------------------------------------------

export class FirestoreJobsRepository implements JobsRepository {
  private readonly uid: string;

  constructor(uid: string) {
    if (!uid) throw new Error('FirestoreJobsRepository requires a user id');
    this.uid = uid;
  }

  private get jobs() {
    return firestore()
      .collection(USERS_COLLECTION)
      .doc(this.uid)
      .collection(JOBS_SUBCOLLECTION);
  }

  async listJobs(options: ListJobsOptions = {}): Promise<Job[]> {
    const { includeArchived = false, orderBy = 'createdAt', orderDirection = 'desc', limit } = options;

    // Archived filtering happens in memory on purpose: a `where('archivedAt', '==', null)`
    // combined with orderBy would require a composite index, and legacy documents in this
    // collection have no `archivedAt` field at all.
    let query = this.jobs.orderBy(orderBy, orderDirection);
    if (typeof limit === 'number') query = query.limit(limit);

    const snapshot = await query.get();

    return snapshot.docs
      .map((doc) => toJob(doc.id, doc.data() as PlainObject))
      .filter((job) => includeArchived || job.archivedAt === null);
  }

  async getJobById(jobId: string): Promise<Job | null> {
    const snapshot = await this.jobs.doc(jobId).get();
    if (!snapshot.exists()) return null;
    return toJob(snapshot.id, snapshot.data() as PlainObject);
  }

  async createJob(input: Omit<CreateJobInput, 'id'>): Promise<Job> {
    // Firestore generates the stable document ID up front, so the domain object and the
    // document it becomes can never disagree about identity.
    const jobRef = this.jobs.doc();
    const job = createJob({ ...input, id: jobRef.id });

    await jobRef.set(toFirestoreData(job));
    return job;
  }

  async updateJob(jobId: string, patch: JobPatch): Promise<Job> {
    const jobRef = this.jobs.doc(jobId);
    const now = new Date().toISOString();

    // Read-modify-write in a transaction, so the returned Job reflects the merged state
    // and `dedupeKey` is recomputed from actual merged values rather than guessed.
    const merged = await firestore().runTransaction(async (transaction) => {
      const snapshot = await transaction.get(jobRef);
      if (!snapshot.exists()) throw new JobNotFoundError(jobId);

      const current = toJob(snapshot.id, snapshot.data() as PlainObject);
      // Strip approval fields from client patches — they are server-owned.
      const sanitized = stripsApprovalFields(patch as PlainObject);
      const changes = withoutUndefined(sanitized);

      const next: Job = {
        ...current,
        ...(changes as Partial<Job>),
        updatedAt: now,
      };

      // If an approved application's material changes, revoke the approval.
      if (needsRevocation(current, changes)) {
        next.approvalStatus = 'pending_review';
        next.approvedAt = null;
        next.approvedBy = null;
      }

      if ('company' in changes || 'role' in changes || 'jobUrl' in changes) {
        next.dedupeKey = computeDedupeKey({
          company: next.company,
          role: next.role,
          jobUrl: next.jobUrl,
        });
      }

      // Only changed keys are written, so untouched fields are preserved verbatim.
      const writeData = withoutUndefined({ ...changes, updatedAt: now });
      if (next.dedupeKey !== current.dedupeKey) writeData.dedupeKey = next.dedupeKey;
      // Include revocation fields if they were added.
      if (needsRevocation(current, changes)) {
        writeData.approvalStatus = 'pending_review';
        writeData.approvedAt = null;
        writeData.approvedBy = null;
      }

      await transaction.update(jobRef, writeData);
      return next;
    });

    return merged as Job;
  }

  async archiveJob(jobId: string, archivedAt?: IsoDateTime): Promise<Job> {
    const jobRef = this.jobs.doc(jobId);
    const stamp = archivedAt ?? new Date().toISOString();

    // Archive is a soft state change, never a delete: the document is retained so the
    // external Sheet and mailbox mirrors stay reconcilable.
    const archived = await firestore().runTransaction(async (transaction) => {
      const snapshot = await transaction.get(jobRef);
      if (!snapshot.exists()) throw new JobNotFoundError(jobId);

      const current = toJob(snapshot.id, snapshot.data() as PlainObject);
      await transaction.update(jobRef, { archivedAt: stamp, updatedAt: stamp });

      return { ...current, archivedAt: stamp, updatedAt: stamp } as Job;
    });

    return archived as Job;
  }

  /**
   * Moves a draft application into review. Requires all review preconditions.
   * Returns the updated job.
   */
  async startReview(jobId: string): Promise<Job> {
    return this.runApprovalTransition(jobId, 'review');
  }

  /**
   * Approves an application that is in `pending_review`.
   * Requires all review preconditions to still hold.
   * Returns the updated job with `approvalStatus: "approved"`.
   */
  async approveJob(jobId: string): Promise<Job> {
    return this.runApprovalTransition(jobId, 'approve');
  }

  /**
   * Rejects an application that is in `pending_review`.
   * Returns the updated job with `approvalStatus: "rejected"`.
   */
  async rejectJob(jobId: string): Promise<Job> {
    return this.runApprovalTransition(jobId, 'reject');
  }

  /**
   * Reopens an approved or rejected application, returning it to `pending_review`.
   * Requires all review preconditions to still hold.
   * Returns the updated job with `approvalStatus: "pending_review"`.
   */
  async reopenJob(jobId: string): Promise<Job> {
    return this.runApprovalTransition(jobId, 'reopen');
  }

  /**
   * Runs an approval transition with the server.
   * The server is the authority; we call the endpoint and return the refreshed job.
   */
  private async runApprovalTransition(jobId: string, action: 'review' | 'approve' | 'reject' | 'reopen'): Promise<Job> {
    const { startReview, approveJob, rejectJob, reopenJob } = await import('../../api/approval');
    const actionMap = {
      review: startReview,
      approve: approveJob,
      reject: rejectJob,
      reopen: reopenJob,
    };
    await actionMap[action](jobId);
    const refreshed = await this.getJobById(jobId);
    if (!refreshed) throw new JobNotFoundError(jobId);
    return refreshed;
  }
}

/** Convenience factory so callers depend on the interface, not the class. */
export function createFirestoreJobsRepository(uid: string): JobsRepository {
  return new FirestoreJobsRepository(uid);
}
